e, +            human(before), +            human(after), +            pct_change(before, after), +        ] +        table.add_row(style(cells, role)) + +    if not markdown: +        table.add_divider() + +    if wheel_after: +        avg_before = sum(wheel_before) // len(wheel_before) if wheel_before else None +        table.add_row( +            style( +                [ +                    f"wheel average ({len(wheel_after)} wheels)", +                    human(avg_before), +                    human(sum(wheel_after) // len(wheel_after)), +                    pct_change(avg_before, sum(wheel_after) // len(wheel_after)), +                ], +                "summary", +            ) +        ) +        table.add_row( +            style( +                [ +                    f"wheel total ({len(wheel_after)} wheels)", +                    human(sum(wheel_before)), +                    human(sum(wheel_after)), +                    pct_change(sum(wheel_before), sum(wheel_after)), +                ], +                "summary", +            ), +            divider=not markdown, +        ) + +    if total_after: +        table.add_row( +            style( +                [ +                    f"artifacts total ({len(total_after)} artifacts)", +                    human(sum(total_before)), +                    human(sum(total_after)), +                    pct_change(sum(total_before), sum(total_after)), +                ], +                "summary", +            ) +        ) + +    title = f"## Dist size comparison vs {baseline_label}" +    if not markdown: +        title = colored(title, attrs=["bold"]) +    return f"{title}

{table.get_string()}
" + + +def main() -> int: +    parser = argparse.ArgumentParser( +        description=__doc__, formatter_class=argparse.ArgumentDefaultsHelpFormatter +    ) +    parser.add_argument( +        "dist_dir", +        type=Path, +        help="Directory containing newly-built wheels and sdist", +    ) +    args = parser.parse_args() + +    if not args.dist_dir.is_dir(): +        print(f"error: {args.dist_dir} is not a directory", file=sys.stderr) +        return 1 + +    baseline_version, baseline_sizes = fetch_pypi_sizes() +    baseline_label = f"Pillow {baseline_version} on PyPI" + +    local_sizes = collect_local_sizes(args.dist_dir) + +    print(render_table(baseline_label, baseline_sizes, local_sizes, markdown=False)) + +    if summary_path := os.environ.get("GITHUB_STEP_SUMMARY"): +        with open(summary_path, "a", encoding="utf-8") as f: +            f.write( +                render_table(baseline_label, baseline_sizes, local_sizes, markdown=True) +            ) + +    return 0 + + +if __name__ == "__main__": +    sys.exit(main())

